#nullable enable // autogenerated

using System;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Models;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Entities
{

    [AutoBuffDefinition(VanillaBuffNames.Entity.teleporterTeleportUp)]
    public class TeleporterTeleportUpBuff : TeleporterBuff
    {
        public TeleporterTeleportUpBuff(string nsp, string name) : base(nsp, name)
        {
            IsUp = true;
            AddModifier(new NamespaceIDArrayModifier(LogicEntityProps.GRID_LAYERS, ArrayOperator.Replace, Array.Empty<NamespaceID>()));
        }
        protected override void OnFinished(Buff buff)
        {
            base.OnFinished(buff);
            var entity = buff.GetEntity();
            if (entity != null)
            {
                entity.Position = GetTargetPosition(buff);
                entity.AddBuff<TeleporterTeleportDownBuff>();
                entity.UpdateModel();
                entity.PlaySound(VanillaSoundID.teleportDown);
            }
        }
        public static Vector3 GetTargetPosition(Buff buff) => buff.GetProperty<Vector3>(PROP_TARGET_POSITION);
        public static void SetTargetPosition(Buff buff, Vector3 value) => buff.SetProperty(PROP_TARGET_POSITION, value);

        public static readonly VanillaBuffPropertyMeta<Vector3> PROP_TARGET_POSITION = new VanillaBuffPropertyMeta<Vector3>("target_position");
    }
}
